module security_alarm (
        input clk,
        input areset,
        input arm,
        input disarm,
        output reg alarm_on);parameter Disarmed=1'b0, Armed=1'b1;
	reg state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= Disarmed;
		else begin
			case (state)
				Disarmed: state <= arm ? Armed : Disarmed;
				Armed: state <= disarm ? Disarmed : Armed;
			endcase
		end
	end

	assign alarm_on = (state == Armed);

endmodule

