module top_module(rst, state, clk, pbl_AI);input wire [1:0] state;
	input wire clk, rst;

	output reg pbl_AI;  								

	reg [10:0] count = 0; 							
	reg [10:0] count_to = 11'b10010101111; 	

	reg new_round; 									

	always@(posedge clk or posedge rst)
	begin
		if(rst) pbl_AI <= 0;							
		else
		begin
			if(state == 2'b00) 						
			begin 
				new_round <= 1;
			end
			else if(state == 2'b00 | state == 2'b10) 
			begin
				if((count == count_to) && new_round)
				begin 
					pbl_AI <= 1;      
					count <= 0;       
					new_round <= 0;   
				end
				else	count <= count + 1'b1;
			end
			if(pbl_AI == 1) pbl_AI <= 0; 			
		end
	end
endmodule

