module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter E=2'b00, F=2'b01, G=2'b10;

    always_comb begin
		case (state)
			E: next_state = in ? G : F;
			F: next_state = in ? E : G;
			G: next_state = in ? F : E;
		endcase
    end

    always_comb begin
		case (state)
			E: out = 1;
			F: out = 0;
			G: out = 1;
		endcase
    end

endmodule

