module top_module(
    input wr_clk,
    input rst,
    input wr_en,
    input [31:0] wr_data,
    input rd_en,
    input rd_clk,
    output [31:0] rd_data,
    output reg full,
    output reg empty,
    output reg almost_full
);parameter FIFO_DEPTH = 16;

reg [31:0] mem [0:FIFO_DEPTH-1];
reg [3:0] wr_ptr_gray, rd_ptr_gray;
reg [3:0] wr_ptr_binary, rd_ptr_binary;
wire [3:0] buf_avail, buf_filled;
wire [2:0] wr_addr, rd_addr;
wire COutb, COutd;
integer i, j, k;

assign wr_addr = wr_ptr_binary[2:0];
assign rd_data = mem[rd_addr];

always @(posedge wr_clk) begin
    if (wr_en && !full) begin
        mem[wr_addr] <= wr_data;
        wr_ptr_gray <= wr_ptr_gray + 1'b1;
    end
end

always @(posedge rd_clk) begin
    if (rst) begin
        rd_ptr_gray <= 4'b0;
        rd_ptr_binary <= 4'b0;
    end else begin
        if (rd_en && !empty) begin
            rd_ptr_gray <= rd_ptr_gray + 1'b1;
        end
    end
end

always @* begin
    wr_ptr_binary = wr_ptr_gray ^ (wr_ptr_gray >> 1);
    rd_ptr_binary = rd_ptr_gray ^ (rd_ptr_gray >> 1);
end

assign {COutb, buf_filled} = wr_ptr_gray - rd_ptr_gray;
assign {COutd, buf_avail} = rd_ptr_gray - wr_ptr_gray + 16;

always @(posedge rd_clk) begin
    if (rst) begin
        empty <= 1'b1;
    end else if ((buf_filled == 0) || (buf_filled == 1 && rd_en)) begin
        empty <= 1'b1;
    end else begin
        empty <= 1'b0;
    end
end

always @(posedge wr_clk) begin
    if (rst) begin
        full <= 1'b0;
        almost_full <= 1'b0;
    end else if ((buf_avail == 0) || (buf_avail == 1 && wr_en)) begin
        full <= 1'b1;
    end else begin
        full <= 1'b0;
    end
    if ((buf_avail == FIFO_DEPTH - 2) || ((buf_avail == FIFO_DEPTH - 3) && wr_en)) begin
        almost_full <= 1'b1;
    end else begin
        almost_full <= 1'b0;
    end
end

assign wr_addr = wr_ptr_binary[2:0];
assign rd_addr = rd_ptr_binary[2:0];

endmodule

