module top_module(
    input wire clock,
    input wire pre_clear,
    input wire data_in,
    output wire data_out
);parameter PIPE_DEPTH = 6;

reg [PIPE_DEPTH - 1 : 0] pipeline;

integer i;

always @(posedge clock or negedge pre_clear) begin
    if (pre_clear == 1'b0) begin
        pipeline <= 0;
    end
    else begin
        for (i = PIPE_DEPTH - 1; i > 0; i = i - 1) begin
            pipeline[i] <= pipeline[i - 1];
        end
        pipeline[0] <= data_in;
    end
end

assign data_out = pipeline[PIPE_DEPTH - 1];

endmodule

