module fsm (
	input clk,
	input reset,
	input a,
	input b,
	output reg o);

	parameter X=0, Y=1, Z1=2, Z2=3, Z3=4, Z4=5, Z5=6;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= X;
		else state <= next;
	end

	always_comb begin
		case (state)
			X: next = a ? Y : X;
			Y: next = b ? Z1 : Z2;
			Z1: next = b ? Z2 : Z3;
			Z2: next = b ? Z3 : Z4;
			Z3: next = b ? Z4 : Z5;
			Z4: next = a ? Y : X;
			Z5: next = a ? Y : X;
			default: next = 'x;
		endcase
	end

	assign o = (state == Z3 && !b);

endmodule

