module piso_shift_register(
    input clk,
    input reset,
    input load,
    input [15:0] data_in,
    output reg serial_out);reg [15:0] shift_reg;
always @(posedge clk) begin
    if (reset)
        shift_reg <= 16'b0000000000000000;
    else if (load)
        shift_reg <= data_in;
    else
        shift_reg <= {shift_reg[14:0], 1'b0};
end
assign serial_out = shift_reg[15];
endmodule

