module fsm (
	input clk,
	input reset,
	input p,
	input q,
	output reg u);

	parameter M=0, N=1, S1=2, S2=3, S3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= M;
		else state <= next;
	end

	always_comb begin
		case (state)
			M: next = p ? N : M;
			N: next = q ? S1 : S2;
			S1: next = q ? S2 : S3;
			S2: next = q ? S1 : M;
			S3: next = p ? N : M;
			default: next = 'x;
		endcase
	end

	assign u = (state == S1);

endmodule

