description:
Design a synchronous first-in-first-out (FIFO) memory module with configurable width and depth for data storage. The module supports writing and reading data while handling reset and flush conditions. It utilizes dual pointers to manage writing and reading operations, indicating when the FIFO is full or empty. The data is stored in a register array, enabling scalable storage of 16-bit wide data entries up to a depth of 512. The module includes logic to control the write and read pointers based on the clock, flush, write, and read signals, ensuring data integrity during operations.
module top_module(

   data_read, full, empty,

   data_write, clk, rst, flush, read, write
   ) ;

code:
module top_module(

   data_read, full, empty,

   data_write, clk, rst, flush, read, write
   ) ;parameter WIDTH = 16;
   parameter DEPTH = 512;
   parameter INDEX_WIDTH = $clog2(DEPTH);

   output wire [WIDTH-1:0] data_read;
   output wire             full;
   output wire             empty;

   input wire [WIDTH-1:0]  data_write;
   input wire              clk;
   input wire              rst;
   input wire              flush;
   input wire              read;
   input wire              write;   






   reg [WIDTH-1:0]         fifo [0:DEPTH-1];




   reg [INDEX_WIDTH-1:0]   read_ptr;
   wire [INDEX_WIDTH-1:0]  read_ptr1;




   reg [INDEX_WIDTH-1:0]   write_ptr;
   wire [INDEX_WIDTH-1:0]  write_ptr1;




   reg                     guard;





   always @(posedge clk)
     if (rst) begin
        write_ptr <= 0;        
     end else if (flush) begin
        write_ptr <= 0;        
     end else if (write) begin
        write_ptr <= write_ptr1;        
     end




   assign write_ptr1 = write_ptr + 1;




   always @(posedge write)
     if (write) begin
        fifo[write_ptr] <= data_write;        
     end





   always @(posedge clk)
     if (rst) begin
        read_ptr <= 0;        
     end else if (flush) begin
        read_ptr <= 0;        
     end else if (read) begin
        read_ptr <= read_ptr1;        
     end




   assign read_ptr1 = read_ptr + 1;




   assign data_read = fifo[read_ptr];




   always @(posedge clk)
     if (rst) begin
        guard <= 0;        
     end else if (flush) begin
        guard <= 0;        
     end else if ((write_ptr1 == read_ptr) && write) begin
        guard <= 1;        
     end else if (read) begin
        guard <= 0;        
     end




   assign empty = (write_ptr == read_ptr) & !guard;




   assign full = (write_ptr == read_ptr) & guard;

endmodule

