description:
Design a glitch filter that stabilizes an input signal by eliminating rapid transitions or noise. The module uses a shift register to track the recent history of the input signal and buffers the filtered output based on a configurable delay and threshold. The output is determined by the state of the buffered signal after a specified delay, ensuring that only stable input levels (either HIGH or LOW) are propagated through the filter. This design is useful in digital systems where clean signal transitions are required.
module top_module(
  input clk,        // Added clk input for the clock signal
  input in,
  output reg out    // Changed output out to reg type to allow assignment in always block
);

code:
module top_module(
  input clk,        // Added clk input for the clock signal
  input in,
  output reg out    // Changed output out to reg type to allow assignment in always block
);parameter t = 4; // threshold value
parameter d = 2; // delay value
parameter b = 8; // output buffer size

reg [b-1:0] buffer;
reg [t-1:0] shift_reg;
reg [t-1:0] prev_input;

always @(posedge clk) begin
  shift_reg <= {shift_reg[t-2:0], in};
  prev_input <= shift_reg;

  if (in == prev_input) begin
    buffer <= {buffer[b-2:0], in};
  end else if (prev_input == {t{1'b1}}) begin
    buffer <= {buffer[b-2:0], 1'b1};
  end else if (prev_input == {t{1'b0}}) begin
    buffer <= {buffer[b-2:0], 1'b0};
  end else begin
    buffer <= {buffer[b-2:0], prev_input};
  end

  out <= buffer[d-1];  // This assignment is now valid since out is a reg
end

endmodule

