module counter_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg en;
    reg resetn;
    wire [7:0] count;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    counter dut (
        .clk(clk),
        .en(en),
        .resetn(resetn),
        .count(count)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(negedge clk);
            resetn = 0;
            en = 0;
            @(negedge clk);
            resetn = 1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Simple Increment", test_num);
            reset_dut();
            en = 1;
            repeat(10) @(negedge clk);
            en = 0;
            #1;

            check_outputs(8'd10);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Enable/Disable functionality", test_num);
            reset_dut();
            en = 1;
            repeat(5) @(negedge clk);
            en = 0;
            repeat(5) @(negedge clk);
            en = 1;
            repeat(5) @(negedge clk);
            en = 0;
            #1;

            check_outputs(8'd10);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Synchronous Reset priority", test_num);
            reset_dut();
            en = 1;
            repeat(15) @(negedge clk);
            resetn = 0;
            @(negedge clk);
            resetn = 1;
            #1;

            check_outputs(8'd0);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Overflow/Wrap-around", test_num);
