module fsm (
    input clk,
    input reset,
    input x,
    input y,
    output reg z);

    parameter S0=0, S1=1, S2=2, S3=3;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    always_comb begin
        case (state)
            S0: next = x ? S1 : S0;
            S1: next = y ? S2 : S0;
            S2: next = y ? S3 : S0;
            S3: next = y ? S1 : S0;
            default: next = 'x;
        endcase
    end

    assign z = (state == S3);

endmodule

